<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import PageHeader from '../components/PageHeader.vue'

const range = ref('近7天')
const cameraIndex = ref(0)
const cameras = ref([])
const clock = ref('')
const toastText = ref('')
let clockTimer
let toastTimer

const rangeValues = {
  近7天:{ orders:'512', bars:[34,59,58,70,70,89,59] },
  近30天:{ orders:'2,184', bars:[72,84,78,91,86,96,90] },
  今日:{ orders:'76', bars:[22,38,30,42,49,61,55] },
}
const fallbackCamera = { code:'CAM-01',name:'检测工位摄像机',type:'摄像机',space:'空间 A / 总览地图 V3.2',status:'在线',camera:{ip:'192.168.20.31',port:'554',protocol:'RTSP',streamUrl:'rtsp://192.168.20.31:554/stream1',resolution:'1920×1080',frameRate:'25',previewUrl:'/assets/camera-detection.png'} }
const bars = computed(() => rangeValues[range.value].bars)
const orders = computed(() => rangeValues[range.value].orders)
const camera = computed(() => cameras.value[cameraIndex.value] || null)
const cameraConfig = computed(() => camera.value?.camera || {})
const cameraImage = computed(() => {
  const value = cameraConfig.value.previewUrl || '/assets/camera-detection.png'
  if (!/\.(png|jpe?g|webp|gif|svg)(\?.*)?$/i.test(value)) return '/assets/camera-detection.png'
  return /^https?:\/\//.test(value) || value.startsWith('/') ? value : `/${value}`
})

function readCameras() {
  try {
    const stored = JSON.parse(localStorage.getItem('agv.peripheral.resources.v1'))
    if (Array.isArray(stored)) cameras.value = stored.filter(item => item.type === '摄像机')
    else cameras.value = [fallbackCamera]
  } catch { cameras.value = [fallbackCamera] }
  cameraIndex.value = 0
}
function updateClock() { clock.value = new Intl.DateTimeFormat('zh-CN',{hour12:false,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date()) }
function toast(message) { toastText.value=message;clearTimeout(toastTimer);toastTimer=window.setTimeout(()=>{toastText.value=''},2200) }
function changeRange() { toast(`已切换统计范围：${range.value}`) }
function onStorage(event) { if(event.key==='agv.peripheral.resources.v1')readCameras() }

onMounted(()=>{readCameras();updateClock();clockTimer=window.setInterval(updateClock,1000);window.addEventListener('storage',onStorage)})
onBeforeUnmount(()=>{clearInterval(clockTimer);clearTimeout(toastTimer);window.removeEventListener('storage',onStorage)})
</script>

<template>
  <div class="page-view capacity-reference-page">
    <PageHeader class="page-head" title="AGV产能" description="分析任务量、机台等待、路径耗时和异常影响" />
    <main class="page-canvas capacity-page">
      <section class="capacity-filter-card"><div class="capacity-filter-copy"><h2>统计条件</h2><p>默认查询近 7 天，切换时间范围后页面指标和趋势图同步刷新</p></div><label class="field-shell capacity-range-field"><span>时间范围</span><select v-model="range" @change="changeRange"><option>近7天</option><option>近30天</option><option>今日</option></select></label></section>

      <section class="capacity-kpis" aria-label="产能指标">
        <article class="capacity-kpi capacity-kpi-success"><div><span>近7天完成订单</span><strong>{{ orders }}</strong><span class="tag success">统计周期内已完成</span></div><span class="kpi-icon"><img src="/assets/lab-capacity/kpi-completed.svg" alt=""></span></article>
        <article class="capacity-kpi capacity-kpi-info"><div><span>近7天完成订单</span><strong>4分32秒</strong><span class="tag info">不含仪器处理</span></div><span class="kpi-icon"><img src="/assets/lab-capacity/kpi-time.svg" alt=""></span></article>
        <article class="capacity-kpi capacity-kpi-warning"><div><span>机台等待占比</span><strong>18.4%</strong><span class="tag warning">主要为贴标机台</span></div><span class="kpi-icon"><img src="/assets/lab-capacity/kpi-wait.svg" alt=""></span></article>
        <article class="capacity-kpi capacity-kpi-error"><div><span>异常影响时长</span><strong>23分钟</strong><span class="tag error">主要为贴标机台</span></div><span class="kpi-icon"><img src="/assets/lab-capacity/kpi-warning.svg" alt=""></span></article>
      </section>

      <section class="capacity-analytics">
        <article class="bar-panel"><div class="capacity-card-head"><h2>节点属性</h2><span class="tag info">单位：单</span></div><div class="bar-chart"><div class="y-axis"><span v-for="n in 11" :key="n" :style="{bottom:`${(n-1)*10}%`}">{{ (n-1)*10 }}</span></div><div class="plot"><i v-for="(value,index) in bars" :key="index" class="bar" :style="{'--height':`${value}%`}" :title="`${value} 单`" /></div><div class="x-axis"><span v-for="day in ['一','二','三','四','五','六','日']" :key="day">{{ day }}</span></div></div></article>
        <aside class="duration-panel"><div class="capacity-card-head"><h2>耗时构成</h2><span class="tag info">近7天</span></div><div class="duration-list">
          <article class="duration-item"><div class="duration-item-head"><span>机台等待</span><strong>50秒</strong></div><div class="duration-progress"><i style="--progress:32%"/><b>32%</b></div></article>
          <article class="duration-item"><div class="duration-item-head"><span>机台等待</span><strong>50秒</strong></div><div class="duration-progress"><i style="--progress:18%"/><b>进度18%</b></div></article>
          <article class="duration-item"><div class="duration-item-head"><span>取放与扫码</span><strong>1分24秒</strong></div><p>42%</p><div class="duration-progress"><i style="--progress:42%"/><b>进度42%</b></div></article>
          <article class="duration-item"><div class="duration-item-head"><span>异常与恢复</span><strong>24秒</strong></div><div class="duration-progress"><i style="--progress:42%"/><b>进度42%</b></div></article>
        </div></aside>
      </section>

      <section class="camera-monitor-panel" aria-labelledby="cameraMonitorTitle"><header class="camera-monitor-head"><div><h2 id="cameraMonitorTitle">实时摄像机画面</h2><p>显示已在“外围资源”中挂载的摄像机检测画面</p></div><label class="camera-select-field"><span>摄像机</span><select v-model.number="cameraIndex" aria-label="选择已挂载摄像机" :disabled="!cameras.length"><option v-if="!cameras.length" :value="0">暂无已挂载摄像机</option><option v-for="(item,index) in cameras" :key="item.code" :value="index">{{ item.name || item.code }} · {{ item.code }}</option></select></label></header>
        <div class="camera-monitor-grid"><article class="camera-feed-card"><div :class="['camera-feed-frame',{'camera-feed-offline':!camera||camera.status==='离线'}]"><img v-if="camera" :src="cameraImage" alt="摄像机实时检测画面"><div class="camera-scan-line" aria-hidden="true"/><div class="camera-feed-osd"><span class="camera-live-dot"/><strong>LIVE</strong><span>{{ camera?.code || '--' }}</span><time>{{ clock }}</time></div><div v-if="!camera" class="camera-feed-empty"><strong>暂无已挂载摄像机</strong><span>请先在外围资源中新增摄像机</span></div></div><footer class="camera-feed-footer"><span><i class="camera-live-dot"/><b>{{ camera?.status || '未挂载' }}</b></span><span>{{ cameraConfig.frameRate ? `${cameraConfig.frameRate} FPS` : '--' }}</span><span>{{ cameraConfig.resolution || '--' }}</span></footer></article>
          <aside class="camera-detail-card"><div class="camera-detail-head"><span>当前设备</span><strong>{{ camera?.name || '--' }}</strong></div><dl class="camera-detail-list"><div><dt>资源编号</dt><dd>{{ camera?.code || '--' }}</dd></div><div><dt>网络地址</dt><dd>{{ camera ? [cameraConfig.ip,cameraConfig.port].filter(Boolean).join(':') || '--' : '--' }}</dd></div><div><dt>码流协议</dt><dd>{{ cameraConfig.protocol || '--' }}</dd></div><div><dt>所属空间</dt><dd>{{ camera?.space || '--' }}</dd></div></dl><div class="camera-result-head"><h3>实时检测</h3><span>正常</span></div><div class="camera-result-list"><article><i/><div><strong>成年实验鼠已识别</strong><span>当前画面 1 个目标</span></div></article><article><i/><div><strong>新生幼鼠多目标识别</strong><span>检测框已标记</span></div></article><article><i/><div><strong>检测区域无遮挡</strong><span>刚刚更新</span></div></article></div></aside>
        </div>
      </section>
    </main>
    <div :class="['toast',{show:toastText}]" role="status" aria-live="polite">{{ toastText }}</div>
  </div>
</template>

